CREATE TABLE IF NOT EXISTS managed_data_objects (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,environment_code VARCHAR(8) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,file_name VARCHAR(191) NOT NULL,payload_text MEDIUMTEXT NOT NULL,content_sha256 CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,size_bytes BIGINT UNSIGNED NOT NULL,revision_version BIGINT UNSIGNED NOT NULL DEFAULT 1,modified_at DATETIME(3) NOT NULL DEFAULT UTC_TIMESTAMP(3),PRIMARY KEY(id),UNIQUE KEY uq_managed_data_object(environment_code,file_name),KEY ix_managed_data_environment(environment_code,file_name),CONSTRAINT ck_managed_data_environment CHECK(environment_code IN('prod','dev'))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS backup_runs (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,operation_id BIGINT UNSIGNED NOT NULL,source_environment VARCHAR(8) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,target_environment VARCHAR(8) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,source_revision_key VARCHAR(80) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,run_status VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,file_count INT UNSIGNED NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT UTC_TIMESTAMP(3),completed_at DATETIME(3) NULL,PRIMARY KEY(id),UNIQUE KEY uq_backup_run_operation(operation_id),CONSTRAINT fk_backup_run_operation FOREIGN KEY(operation_id) REFERENCES operations(id),CONSTRAINT ck_backup_run_status CHECK(run_status IN('processing','complete','failed'))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS backup_manifest (run_id BIGINT UNSIGNED NOT NULL,file_name VARCHAR(191) NOT NULL,source_object_id BIGINT UNSIGNED NOT NULL,source_revision BIGINT UNSIGNED NOT NULL,content_sha256 CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,size_bytes BIGINT UNSIGNED NOT NULL,modified_at DATETIME(3) NOT NULL,PRIMARY KEY(run_id,file_name),CONSTRAINT fk_backup_manifest_run FOREIGN KEY(run_id) REFERENCES backup_runs(id) ON DELETE CASCADE,CONSTRAINT fk_backup_manifest_source FOREIGN KEY(source_object_id) REFERENCES managed_data_objects(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS backup_run_items (run_id BIGINT UNSIGNED NOT NULL,file_name VARCHAR(191) NOT NULL,target_object_id BIGINT UNSIGNED NOT NULL,item_status VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,before_sha256 CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL,after_sha256 CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,completed_at DATETIME(3) NOT NULL,PRIMARY KEY(run_id,file_name),CONSTRAINT fk_backup_item_run FOREIGN KEY(run_id) REFERENCES backup_runs(id) ON DELETE CASCADE,CONSTRAINT fk_backup_item_target FOREIGN KEY(target_object_id) REFERENCES managed_data_objects(id),CONSTRAINT ck_backup_item_status CHECK(item_status IN('copied','skipped','failed'))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
START TRANSACTION;
INSERT INTO admin_permissions(code,display_name) VALUES('data_backup.execute','운영 데이터 DEV 백업') ON DUPLICATE KEY UPDATE display_name=VALUES(display_name);
INSERT INTO admin_role_permissions(role_id,permission_code) SELECT id,'data_backup.execute' FROM admin_roles WHERE code='super_admin' AND active=TRUE ON DUPLICATE KEY UPDATE permission_code=VALUES(permission_code);
INSERT INTO command_registry(command_code,handler_key,auth_scope,rollout_state,enabled,version) VALUES('ADMIN_DATA_BACKUP','admin_data_backup','VERIFIED_USER','SHADOW',TRUE,1) ON DUPLICATE KEY UPDATE handler_key=VALUES(handler_key),auth_scope=VALUES(auth_scope),rollout_state=VALUES(rollout_state),enabled=TRUE,version=version+1;
INSERT INTO command_aliases(command_text,command_code,active) VALUES('dev/데이터백업','ADMIN_DATA_BACKUP',TRUE) ON DUPLICATE KEY UPDATE command_code=VALUES(command_code),active=TRUE;
COMMIT;
